-- Currency formatting: symbols and decimal places of the currencies (System Options currency table).
-- Read by pjMoney (back office) and pjJabbApi::currencySign (website). Existing rows / symbols are kept; only missing
-- currencies are added. The symbols can be changed in this table at any time (data, not code).

ALTER TABLE `plugin_base_currencies` ADD COLUMN IF NOT EXISTS `decimals` tinyint(1) unsigned NOT NULL DEFAULT '2';


UPDATE `plugin_base_currencies` SET `decimals` = 0 WHERE `code` IN ('BIF', 'CLP', 'DJF', 'GNF', 'ISK', 'JPY', 'KMF', 'KRW', 'PYG', 'RWF', 'UGX', 'UYI', 'VND', 'VUV', 'XAF', 'XOF', 'XPF');
UPDATE `plugin_base_currencies` SET `decimals` = 3 WHERE `code` IN ('BHD', 'IQD', 'JOD', 'KWD', 'LYD', 'OMR', 'TND');
UPDATE `plugin_base_currencies` SET `sign` = 'A$' WHERE `code` = 'AUD' AND (`sign` IS NULL OR `sign` = '');
